Class Machine
  Define stock, collected, price As Integer;

  Method Constructor(cans As Integer)
    This.stock <- cans;
    This.collected <- 0;
    This.price <- 3;
  EndMethod

  Method Sell() As Boolean
    If This.stock = 0 Then
      Return False;
    EndIf
    This.stock <- This.stock - 1;
    This.collected <- This.collected + This.price;
    Return True;
  EndMethod

  Method Estado() As String
    Return toText(This.stock) + " cans, " + toText(This.collected) + " pesos";
  EndMethod
EndClass

Algorithm Kiosk
  Define machineOne As Machine <- New Machine(10);
  Define machineTwo As Machine <- New Machine(10);
  Define number As Integer;
  Read number;
  While number <> 0 Do
    If number = 1 Then
      If Not machineOne.Sell() Then
        Write "Machine 1 has no cans";
      EndIf
    Else
      If Not machineTwo.Sell() Then
        Write "Machine 2 has no cans";
      EndIf
    EndIf
    Read number;
  EndWhile
  Write "Machine 1: ", machineOne.Estado();
  Write "Machine 2: ", machineTwo.Estado();
EndAlgorithm
